UPDATE law_api_sync_history
SET status = 'SUCCESS', response_json = #{responseJson}, finished_at = CURRENT_TIMESTAMP
WHERE sync_history_id = #{historyId}

UPDATE law_api_sync_history
SET status = 'FAILED', error_message = #{errorMessage}, finished_at = CURRENT_TIMESTAMP
WHERE sync_history_id = #{historyId}
